pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockNumber) public {
        // Restrict amount to the admissible domain: any value that could be sent
        vm.assume(amount <= 100 ether);

        // Restrict blockNumber to a valid range
        vm.assume(blockNumber > 0 && blockNumber < type(uint256).max);

        // Set block number and timestamp
        vm.roll(blockNumber);
        // Warp to a future timestamp so pastBlockTime is always behind
        vm.warp(block.timestamp + 100);

        // Fund a caller and attempt the fallback
        address caller = makeAddr("caller");
        vm.deal(caller, amount);

        bool ok;
        uint256 recordedTime;
        vm.prank(caller);
        try c.fallback{value: amount}() {
            ok = true;
            recordedTime = c.pastBlockTime();
        } catch {
            ok = false;
        }

        // Assert: if the call succeeded (non-reverting), pastBlockTime must equal the current block.timestamp.
        // The reference accepts only 10 ether, so for amount==10 ether it succeeds and updates pastBlockTime.
        // The buggy version requires 11 ether, so for amount==10 ether it reverts and never updates pastBlockTime,
        // failing this rule when the fuzzer picks exactly 10 ether.
        if (ok) {
            assertEq(recordedTime, block.timestamp);
        }
    }
}

