pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 blockTimestamp) public {
        // Constrain the fuzzed inputs to feasible EVM values
        blockNumber = bound(blockNumber, 1, type(uint256).max - 1);
        blockTimestamp = bound(blockTimestamp, 1, type(uint256).max);

        // Set block number and timestamp for the first call
        vm.roll(blockNumber);
        vm.warp(blockTimestamp);

        // Fund a caller and make the first fallback call
        address caller = makeAddr("caller");
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Record state after first call
        uint256 pastBlockTimeAfterFirst = c.pastBlockTime();
        uint256 balanceAfterFirst = address(c).balance;

        // Second call in the SAME block with same timestamp
        // The block number is the same because vm.roll was not called again.
        // The timestamp is the same because vm.warp was not called again.
        // The mutant allows block.timestamp >= pastBlockTime, so this call succeeds.
        // The reference requires block.timestamp > pastBlockTime, so this call reverts.
        bool secondCallSucceeded;
        vm.prank(caller);
        try c.f{value: 10 ether}() {
            secondCallSucceeded = true;
        } catch {
            secondCallSucceeded = false;
        }

        uint256 pastBlockTimeAfterSecond = c.pastBlockTime();
        uint256 balanceAfterSecond = address(c).balance;

        if (secondCallSucceeded) {
            // If the second call succeeded (mutant behavior), pastBlockTime must have been updated
            // to the current block timestamp, so it equals the timestamp of both calls.
            assertTrue(pastBlockTimeAfterSecond == blockTimestamp);
        } else {
            // If the second call reverted (reference behavior), pastBlockTime must be unchanged
            // from the first call. Therefore, pastBlockTimeAfterSecond equals pastBlockTimeAfterFirst.
            assertTrue(pastBlockTimeAfterSecond == pastBlockTimeAfterFirst);
        }
    }
}

