pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNumber1, uint256 blockNumber2, uint8 amountIdx) public {
        // Admissible domain: two calls with exactly 10 ETH, same timestamp, and distinct block numbers where the second triggers a payout
        vm.assume(amountIdx < 2);
        vm.assume(blockNumber1 != blockNumber2);
        vm.assume(blockNumber2 % 15 == 0); // second call triggers payout
        vm.warp(timestamp);

        address alice = address(0x1000);
        address bob = address(0x2000);
        vm.deal(alice, 20 ether);
        vm.deal(bob, 20 ether);

        // First call by alice
        vm.roll(blockNumber1);
        vm.prank(alice);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "call1 failed");

        // Second call by bob at the SAME timestamp, triggering payout on reference
        vm.roll(blockNumber2);
        vm.prank(bob);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // The rule: second call at the same timestamp MUST revert (reference) or succeeds (mutant)
        // In the reference, the require(block.timestamp > pastBlockTime) fails, so the balance remains 20 ether.
        // In the mutant, it succeeds, transfers entire balance to bob, and contract balance becomes 0.
        assertTrue(!ok2 || address(c).balance == 0);
    }
}

