import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockTime, uint256 blockNum1, uint256 blockNum2) public {
        // Ensure blockNum2 >= blockNum1 to keep ordering meaningful
        vm.assume(blockNum2 >= blockNum1);
        // Ensure time is within reasonable bounds
        vm.assume(blockTime < type(uint64).max);
        // Ensure block numbers are within reasonable bounds
        vm.assume(blockNum1 < type(uint64).max);
        vm.assume(blockNum2 < type(uint64).max);

        address actor = makeAddr("actor");
        uint256 sendValue = 10 ether;
        vm.deal(actor, sendValue * 2);

        // First call in block blockNum1 at time blockTime
        vm.roll(blockNum1);
        vm.warp(blockTime);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: sendValue}("");
        require(ok1, "First call failed");
        uint256 pastBlockTimeAfterFirst = c.pastBlockTime();

        // Second call in block blockNum2 at time blockTime (same time)
        // If blockNum2 equals blockNum1, the call happens in the same block.
        vm.roll(blockNum2);
        vm.warp(blockTime);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: sendValue}("");

        // The invariant: If the second call succeeded, the stored pastBlockTime must be strictly greater
        // than before the call, OR the call must have reverted.
        // In the reference contract, a same-timestamp call reverts because of the require check.
        // In the mutant, it succeeds and sets pastBlockTime to the same value.
        bool invariantHolds = !ok2 || c.pastBlockTime() > pastBlockTimeAfterFirst;
        assertTrue(invariantHolds, "Invariant violated: pastBlockTime did not increase on successful call");
    }
}

