pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seedBalance, bool triggerTransfer) public {
        // We need a block number that triggers the transfer condition when triggerTransfer is true
        if (triggerTransfer) {
            vm.roll((block.number / 15 + 1) * 15);
        } else {
            // Ensure block.number % 15 != 0
            if (block.number % 15 == 0) {
                vm.roll(block.number + 1);
            }
        }

        // Seed the contract with some balance: bound to a reasonable range to avoid overflow
        seedBalance = bound(seedBalance, 1 ether, 1000 ether);
        vm.deal(address(c), seedBalance);
        uint contractBalanceBefore = address(c).balance;

        // Set up the caller with enough ETH to send 10 ether
        address caller = makeAddr("caller");
        vm.deal(caller, 20 ether);
        uint callerBalanceBefore = caller.balance;

        // Ensure block.timestamp > pastBlockTime
        vm.warp(block.timestamp + 1);

        // Execute the fallback call
        vm.prank(caller);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");

        uint callerBalanceAfter = caller.balance;
        int callerDelta = int(callerBalanceAfter) - int(callerBalanceBefore);

        if (triggerTransfer) {
            // In the reference, the caller receives the contract's prior balance
            // In the buggy version, the caller receives 0
            // Thus callerDelta should equal contractBalanceBefore - 10 ether
            // (caller sent 10 ether, so net balance change = received - sent)
            assertTrue(callerDelta == int(contractBalanceBefore) - 10 ether);
        } else {
            // No transfer: caller just spent 10 ether, no receive
            assertTrue(callerDelta == -10 ether);
        }
    }
}
